function setup() {
	createCanvas(windowWidth, windowHeight);
	background("#ddeeff");
	colorMode(HSB)
}

function draw() {
	translate(width/2,-height/8)

	noFill()
	strokeWeight(30)
	for (let i = 0; i < 10; i++) {
		stroke(abs(360 - (330 + i * 30)) % 360, 25, 75)
		const d = i * 80 + height/2;
		arc(0, 0, d, d, 0, HALF_PI + i * PI/16)
	}

	// noLoop() removed for animation
}
